    expect(sympyStr(piecewise([new Mul([rational(1, 2), new Pow(x, rational(2))]), And(rel('Ge', x, 0), rel('Le', x, 1))], [new Add([rational(-2), new Mul([rational(4), x]), new Mul([rational(-3, 2), new Pow(x, rational(2))])]), And(rel('Ge', x, 1), rel('Le', x, 2))], [rational(0), true]))).toBe('Piecewise((x**2/2, (x >= 0) & (x <= 1)), (-3*x**2/2 + 4*x - 2, (x >= 1) & (x <= 2)), (0, True))');
